import{_ as a,o as r,c as t,a5 as l}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 45 话 @layer 进阶：嵌套层、匿名层与 revert-layer","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.45-layer-advanced.md","filePath":"comics/css/EP.45-layer-advanced.md","lastUpdated":1793421609000}'),o={name:"comics/css/EP.45-layer-advanced.md"};function s(d,e,i,c,n,h){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="漫画-·-第-45-话-layer-进阶-嵌套层、匿名层与-revert-layer" tabindex="-1">漫画 · 第 45 话 @layer 进阶：嵌套层、匿名层与 revert-layer <a class="header-anchor" href="#漫画-·-第-45-话-layer-进阶-嵌套层、匿名层与-revert-layer" aria-label="Permalink to &quot;漫画 · 第 45 话 @layer 进阶：嵌套层、匿名层与 revert-layer&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/28-layer-advanced">docs/css/28-layer-advanced.md</a> ｜ 原画：<a href="./EP.45-layer-advanced.svg">EP.45-layer-advanced.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。基础 @layer 用熟了，但大型项目里 base 层内还要分 reset/tokens/typography、第三方库 CSS 没进层、组件覆盖后想回退到 base——基础层叠层不够用了。</li><li><strong>标签君</strong>：HTML5 结构师，搬出进阶三件套——嵌套层让层内再分层、匿名层包裹第三方 CSS、revert-layer 精确撤销某一层覆盖。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>EP.23 解决了「层叠顺序可控」，但真实项目复杂度升级：设计系统要分层、Ant Design 产物要隔离、覆盖后要回退。像素酱学会三件进阶武器——<code>@layer base { @layer reset { } }</code> 嵌套层分组管理、<code>@layer { }</code> 匿名层包裹第三方、<code>revert-layer</code> 回退到上一层而非浏览器默认。大型项目的层叠战争终于消停。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>三个新痛点：base 层内还要再分 reset/tokens/typography；第三方库（如 Ant Design）没有 @layer，直接插进层叠打乱顺序；组件覆盖了 base 的颜色，想回退到 base 而不是浏览器默认。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>嵌套层 <code>@layer base { @layer reset { } }</code> 形成树状层叠，顺序 = 父层顺序 + 子层声明顺序；匿名层 <code>@layer { }</code> 不带名字，排在所有命名层之后，用于包裹第三方 CSS；<code>revert-layer</code> 把属性回退到上一层，而不是浏览器默认（revert）或初始值（initial）。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：嵌套层分组（大型设计系统分层）、匿名层包裹第三方（隔离不污染）、revert-layer（精确撤销覆盖）、第三方库覆盖（antd 固定在底层，components 永远覆盖）。无需 !important 或特异性战争。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>嵌套层顺序 = 父层顺序 + 子层声明顺序；最多两层，三层可读性急剧下降。</li><li>匿名层只用于包裹第三方 CSS；业务代码必须进命名层，否则无法追加。</li><li>revert-layer 回退到上一层，revert 回退到浏览器默认——别搞混。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么匿名层不能用于业务代码，只能包裹第三方 CSS？</p><p><strong>答</strong>：匿名层没有名字，后续无法用 <code>@layer</code> 引用追加内容。业务代码需要不断迭代（今天加按钮、明天加卡片），必须进命名层才能持续追加；第三方库产物是静态的，一次性包裹即可。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>嵌套层演示 + 匿名层包裹 + revert-layer 回退 + 第三方库覆盖：<a href="./../../examples/css/28-layer-advanced/index-01-layer-advanced.html">examples/css/28-layer-advanced/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 46 话《Service Worker 缓存策略》——地铁上打不开页面？Cache First 静态资源、Network First API、Stale While Revalidate 列表，三大策略让应用离线可用、秒开。</p>',22)])])}const u=a(o,[["render",s]]);export{p as __pageData,u as default};
